import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- TOTALS ----
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(total_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    if df['Revenue_LY'].notna().any():
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(total_rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(float(total_units_tw), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(float(total_units_lw), 2),
        "formula": "sum(Units_LW)"
    })

    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(float(total_orders_tw), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(float(total_orders_lw), 2),
        "formula": "sum(Orders_LW)"
    })

    if total_rev_lw != 0 and pd.notna(total_rev_lw):
        total_wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(total_wow), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly != 0 and pd.notna(total_rev_ly):
        total_yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(total_yoy), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- TOP ENTITIES BY REVENUE (TW) ----
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "TW",
            "value": round(float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

    # ---- TOP SHARE ----
    if df['Share_Pct'].notna().any():
        top_share_row = df.loc[df['Share_Pct'].idxmax()]
        facts.append({
            "entity": str(top_share_row['Entity']),
            "metric": "share",
            "period": "TW",
            "value": round(float(top_share_row['Share_Pct']), 1),
            "formula": "Share_Pct"
        })

    # ---- RANK 1 ENTITY ----
    if df['Rank'].notna().any():
        rank1_row = df.loc[df['Rank'].idxmin()]
        facts.append({
            "entity": str(rank1_row['Entity']),
            "metric": "rank",
            "period": "TW",
            "value": float(rank1_row['Rank']),
            "formula": "Rank"
        })

    # ---- TOP 5 WoW GAINERS ----
    wow_valid = df.dropna(subset=['WoW_Pct'])
    top_wow_gain = wow_valid.sort_values('WoW_Pct', ascending=False).head(5)
    for _, row in top_wow_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- BIGGEST WoW DECLINER ----
    if not wow_valid.empty:
        worst_wow_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": str(worst_wow_row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": round(float(worst_wow_row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- TOP 5 YoY GAINERS ----
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    top_yoy_gain = yoy_valid.sort_values('YoY_Pct', ascending=False).head(5)
    for _, row in top_yoy_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "YoY",
            "value": round(float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # ---- BIGGEST YoY DECLINER ----
    if not yoy_valid.empty:
        worst_yoy_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": str(worst_yoy_row['Entity']),
            "metric": "revenue",
            "period": "YoY",
            "value": round(float(worst_yoy_row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
